import './ProductGrid.css';

export type Product = {
  id: string;
  name: string;
  category: string;
};

type ProductGridProps = {
  products: Product[];
  status: 'loading' | 'loaded';
};

const GHOST_COUNT = 6;

export function ProductGrid({ products, status }: ProductGridProps): JSX.Element {
  if (status === 'loading') {
    return (
      <ul role="list" className="product-grid">
        {Array.from({ length: GHOST_COUNT }, (_, i) => (
          <li key={i} className="product-card product-card--ghost">
            <div className="ghost-line ghost-line--title" />
            <div className="ghost-line ghost-line--meta" />
          </li>
        ))}
      </ul>
    );
  }

  return (
    <ul role="list" className="product-grid">
      {products.map((product) => (
        <li key={product.id} className="product-card">
          <p className="product-card-title">{product.name}</p>
          <p className="product-card-meta">{product.category}</p>
        </li>
      ))}
    </ul>
  );
}
